/**
 * Argument parsing for the chisme CLI.
 *
 * Wraps Node's built-in `util.parseArgs` (available in Bun) and adds the inline
 * filter parser: `author:`, `date:`, `branch:`, and `repo:` embedded in the query
 * string, with optional quoted values. Explicit flags take precedence over inline
 * filters when both are present.
 */
import { parseArgs, type ParseArgsConfig } from "node:util";

export interface InlineFilters {
  text: string;
  author?: string;
  branch?: string;
  date?: string;
  repo?: string;
}

const INLINE = /\b(author|date|branch|repo):("([^"]*)"|'([^']*)'|(\S+))/gi;

/** Pulls `key:value` filters out of a query string, returning them and the rest. */
export function parseInlineFilters(query: string): InlineFilters {
  const filters: InlineFilters = { text: "" };
  const stripped = query.replace(INLINE, (_m, key: string, _v, dq, sq, bare) => {
    const value = dq ?? sq ?? bare ?? "";
    (filters as Record<string, string>)[key.toLowerCase()] = value;
    return " ";
  });
  filters.text = stripped.replace(/\s+/g, " ").trim();
  return filters;
}

function toInt(value: string | undefined, fallback: number): number {
  if (value == null) return fallback;
  const n = Number.parseInt(value, 10);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

function coerceDate(value: string | undefined): "week" | "month" | undefined {
  return value === "week" || value === "month" ? value : undefined;
}

export interface SearchArgs {
  query: string;
  json: boolean;
  limit: number;
  page: number;
  author?: string;
  branch?: string;
  date?: "week" | "month";
  repo?: string;
  semantic: boolean;
  help: boolean;
}

function parse(argv: string[], options: ParseArgsConfig["options"]) {
  return parseArgs({ args: argv, options, allowPositionals: true, strict: true });
}

export function parseSearchArgs(argv: string[]): SearchArgs {
  const { values, positionals } = parse(argv, {
    json: { type: "boolean" },
    limit: { type: "string" },
    page: { type: "string" },
    author: { type: "string" },
    branch: { type: "string" },
    date: { type: "string" },
    repo: { type: "string" },
    semantic: { type: "boolean" },
    "no-semantic": { type: "boolean" },
    help: { type: "boolean", short: "h" },
  });

  const inline = parseInlineFilters(positionals.join(" "));

  return {
    query: inline.text,
    json: Boolean(values.json),
    limit: toInt(values.limit as string | undefined, 25),
    page: toInt(values.page as string | undefined, 1),
    author: (values.author as string | undefined) ?? inline.author,
    branch: (values.branch as string | undefined) ?? inline.branch,
    date: coerceDate((values.date as string | undefined) ?? inline.date),
    repo: (values.repo as string | undefined) ?? inline.repo,
    semantic: values["no-semantic"] ? false : true,
    help: Boolean(values.help),
  };
}

export interface SyncArgs {
  full: boolean;
  remote: string;
  help: boolean;
}

export function parseSyncArgs(argv: string[]): SyncArgs {
  const { values } = parse(argv, {
    full: { type: "boolean" },
    remote: { type: "string" },
    help: { type: "boolean", short: "h" },
  });
  return {
    full: Boolean(values.full),
    remote: (values.remote as string | undefined) ?? "origin",
    help: Boolean(values.help),
  };
}

export interface ListArgs {
  repo?: string;
  limit: number;
  json: boolean;
  help: boolean;
}

export function parseListArgs(argv: string[]): ListArgs {
  const { values } = parse(argv, {
    repo: { type: "string" },
    limit: { type: "string" },
    json: { type: "boolean" },
    help: { type: "boolean", short: "h" },
  });
  return {
    repo: values.repo as string | undefined,
    limit: toInt(values.limit as string | undefined, 25),
    json: Boolean(values.json),
    help: Boolean(values.help),
  };
}

